#include <queue>
#include <set>
using namespace std;

class MKAverage {
    int m, k;
    queue<int> q;
    multiset<int> lo, mid, hi;
    long long midSum = 0;

public:
    MKAverage(int m_, int k_) : m(m_), k(k_) {}

    void addElement(int num) {
        q.push(num);
        lo.insert(num);

        if (lo.size() > k) {
            mid.insert(*lo.rbegin());
            midSum += *lo.rbegin();
            lo.erase(prev(lo.end()));
        }

        if (mid.size() > m - 2 * k) {
            hi.insert(*mid.rbegin());
            midSum -= *mid.rbegin();
            mid.erase(prev(mid.end()));
        }

        if (q.size() > m) {
            int old = q.front(); q.pop();
            if (lo.count(old)) lo.erase(lo.find(old));
            else if (mid.count(old)) {
                mid.erase(mid.find(old));
                midSum -= old;
            } else hi.erase(hi.find(old));

            if (lo.size() < k && !mid.empty()) {
                lo.insert(*mid.begin());
                midSum -= *mid.begin();
                mid.erase(mid.begin());
            }

            if (mid.size() < m - 2 * k && !hi.empty()) {
                mid.insert(*hi.begin());
                midSum += *hi.begin();
                hi.erase(hi.begin());
            }
        }
    }

    int calculateMKAverage() {
        if (q.size() < m) return -1;
        return midSum / (m - 2 * k);
    }
};
